#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression:

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // ---------------------------
    // Scheduling for init_array()
    // ---------------------------

    // The computation is O(n^3); we want to:
    //  - keep A0 inlined (it's a very cheap expression)
    //  - parallelize across 'i' (rows)
    //  - vectorize across 'j' (columns)
    //
    // This gives us good multi-core usage and SIMD utilization while
    // keeping memory usage modest (we do not materialize A0).

    int vec = natural_vector_size(type_of<num_t>());

    // Compute B at the root; we'll write it directly into A.
    B.compute_root();

    // Parallelize the reduction across rows and vectorize across columns.
    Var jo("jo"), ji("ji");
    B.update()
        // Make the loop nest: for i (rows) in parallel, inside that j (cols) in
        // vectorized chunks, inside that the reduction variable t.
        .reorder(j, i, t.x)
        .split(j, jo, ji, vec)
        .vectorize(ji)
        .parallel(i);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and j on the host (as required to
    //     preserve the sequential dependencies).
    //   - Use a Halide reduction Func to compute the inner summation over k:
    //         sum_{k < min(i, j)} A[i][k] * A[k][j]
    //
    //     which covers both original cases:
    //       * j <  i: sum_{k < j}
    //       * j >= i: sum_{k < i}
    //
    //   - We use ImageParam + Param<int> for i and j, and realize a scalar
    //     Func for each (i, j) where needed.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Func below. The
    // in-place updates to A are done on the host after each scalar realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Func to compute:
    //   A[i][j] - sum_{k=0}^{min(i,j)-1} A[i][k] * A[k][j]
    //
    // This single definition covers:
    //   - L-part (j < i): sum over k < j
    //   - U-part (j >= i): sum over k < i
    Func elem("elem");
    {
        // Base value: A[i][j] in C corresponds to A_param(j_param, i_param)
        elem() = A_param(j_param, i_param);

        // Upper bound of k: min(i, j)
        Expr upper = min(i_param, j_param);

        // Sum over k = 0 .. upper-1:
        //   A[i][j] -= A[i][k] * A[k][j]
        //
        // Mapping:
        //   A[i][k] -> A_param(k,       i_param)
        //   A[k][j] -> A_param(j_param, k      )
        RDom k(0, upper, "k");
        elem() -= A_param(k, i_param) * A_param(j_param, k);

        // Schedule the reduction over k:
        elem.compute_root();

        int vec_k = natural_vector_size(type_of<num_t>());
        // Vectorize the reduction over k. Halide will handle non-multiples.
        elem.update()
            .vectorize(k.x, vec_k);
    }

    // JIT-compile the scalar pipeline once; we will reuse it for all (i, j).
    elem.compile_jit();

    // Reusable 0-D buffer to avoid reallocating for every (i,j).
    // make_scalar() gives us a scalar buffer that we can repeatedly
    // realize into without extra allocations.
    Halide::Buffer<num_t> elem_buf = Halide::Buffer<num_t>::make_scalar();

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1  (L part)
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            elem.realize(elem_buf);
            num_t val = elem_buf();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (U part)
        for (int j = i; j < n; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            elem.realize(elem_buf);
            num_t val = elem_buf();  // zero-dimensional buffer

            // Store back into A[i][j] (no division here)
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
