    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // Lower-triangular matrix, 1.0 on diagonal, strictly-lower as in Polybench:
    //
    // if (j <= i) {
    //   if (i == j)      A[i][j] = 1;
    //   else            A[i][j] = (DATA_TYPE)(-j) / n + 1;
    // } else {
    //   A[i][j] = 0;
    // }
    //
    // Recall: A[i][j] in C -> A0(j, i) in Halide.
    A0(j, i) = select(
        j <= i,
        select(i == j,
               one,                                   // diagonal
               cast<num_t>(-j) / n_val + one),       // strictly lower
        zero);                                       // above diagonal

    // Make the matrix symmetric positive semi-definite:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // B(r, s) in C -> B(j, i) in Halide
    // A[r][t]      -> A0(t, r) -> A0(t, i)
    // A[s][t]      -> A0(t, s) -> A0(t, j)
    //
    // B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)
    RDom t(0, n, "t");

    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // ----------------------------
    // Schedule for better locality
    // ----------------------------
    //
    // Compute B at the root, parallel over rows (i) and vectorize over
    // columns (j). Apply the same strategy to the reduction update.
    //
    // This keeps the algorithm unchanged but improves CPU utilization
    // during initialization, which can be significant for large n.
    B.compute_root()
        .parallel(i)
        .vectorize(j, 8);

    B.update()
        .parallel(i)
        .vectorize(j, 8);

    // Realize B directly into the provided buffer A (equivalent to
    // computing B then copying into A in the C version).
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and the first inner loop over j on
    //     the host (to preserve dependencies in the "L" factor).
    //
    //   - Use Halide Funcs to compute:
    //       • For j < i (L part):   A[i][j] - sum_{k<j} A[i][k] * A[k][j]
    //         (scalar Func per (i, j), evaluated sequentially in j).
    //
    //       • For j ≥ i (U part):   A[i][j] - sum_{k<i} A[i][k] * A[k][j]
    //         (vector Func over all j ≥ i for a given i, evaluated in
    //          one shot for the entire trailing row segment).
    //
    //   - We use ImageParam + Param<int> for indices and realize into
    //     scalars or 1D buffers as appropriate.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Func to compute A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for the case j < i (the "L" part), before dividing by A[j][j].
    //
    // A[i][j] in C corresponds to A_param(j_param, i_param)
    Func left_elem("left_elem");
    {
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k_left, i_param)
        // A[k][j] -> A_param(j_param, k_left)
        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
    }

    // Func to compute the whole trailing part of row i at once:
    //
    // For all j ∈ [i, n):
    //   A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // We express j relatively as j_rel = j - i, so that the Func domain
    // is 0 .. (n-i-1) and we can realize a 1D buffer:
    //
    //   out[j_rel] = A[i][i + j_rel] - sum_{k<i} A[i][k] * A[k][i + j_rel]
    //
    // This has no dependencies across j, so computing all j ≥ i for a
    // row in a single Halide realization is safe and improves locality.
    Var j_rel("j_rel");
    Func row_update("row_update");
    {
        // Base value A[i][i + j_rel]
        row_update(j_rel) = A_param(j_rel + i_param, i_param);

        // Sum over k = 0 .. i-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k]       -> A_param(k_row, i_param)
        // A[k][j]       -> A_param(j_rel + i_param, k_row)
        RDom k_row(0, i_param, "k_row");
        row_update(j_rel) += cast<num_t>(-1) *
                             A_param(k_row, i_param) *
                             A_param(j_rel + i_param, k_row);
    }

    // ----------------------------
    // Scheduling for the kernels
    // ----------------------------

    // Simple vectorization for row_update along j_rel. This vectorizes
    // both the pure and update steps; k_row remains scalar.
    //
    // We choose a fixed width (8) for portability; Halide will handle
    // edge cases when the extent is not a multiple of 8.
    row_update.vectorize(j_rel, 8);
    row_update.update().vectorize(j_rel, 8);

    // JIT-compile the pipelines once; we will reuse them for all (i, j).
    Target target = get_jit_target_from_environment();
    left_elem.compile_jit(target);
    row_update.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // -------------------------------------------------------------
        // First inner loop: j = 0 .. i-1  (L factor, sequential in j)
        // -------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // -------------------------------------------------------------
        // Second inner loop: j = i .. n-1  (U factor)
        //
        // Original code computes each A[i][j] independently for fixed i.
        // We exploit this and compute the entire trailing row segment
        // [i, n) in a single Halide realization for better locality and
        // fewer JIT calls.
        // -------------------------------------------------------------
        i_param.set(i);

        int len = n - i;  // number of columns j >= i
        Halide::Buffer<num_t> row_buf(len);

        // row_buf(j_rel) corresponds to A[i][i + j_rel] after subtracting
        // the sum_{k<i} term.
        row_update.realize(row_buf);

        // Copy results back into A:
        for (int j_rel_idx = 0; j_rel_idx < len; j_rel_idx++) {
            int j = i + j_rel_idx;   // absolute column index
            // Store back into A[i][j] (A(j, i) in Halide)
            A(j, i) = row_buf(j_rel_idx);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
