    // Scheduling for B
    // --------------------
    // The Gram matrix B is n x n, with a reduction over t.
    // We:
    //   - compute at root
    //   - parallelize across rows (i), which are independent
    //   - vectorize across columns (j) to improve memory throughput
    Target target = get_host_target();
    const int vec_width = Halide::natural_vector_size(target, type_of<num_t>());

    // Pure definition: initialize B(j, i) = 0 in parallel over rows,
    // and vectorize across columns when possible.
    B.compute_root().parallel(i);
    if (vec_width > 1) {
        B.vectorize(j, vec_width);
    }

    // Update definition: also parallelize rows and vectorize columns.
    B.update().parallel(i);
    if (vec_width > 1) {
        B.update().vectorize(j, vec_width);
    }

    // JIT-compile once and realize directly into the provided buffer A.
    B.compile_jit(target);
    B.realize(A);
