    // are known, so we can compute the whole row in one 1D pipeline call.
    //
    // Mapping:
    //   A[i][j] -> A_param(j, i_param)
    //   A[i][k] -> A_param(k, i_param)
    //   A[k][j] -> A_param(j, k)
    // -------------------------------------------------------------------------
    Var j_var("j_var");
    Func row_upper("row_upper");
