    // Scheduling for row_upper
    // --------------------
    // We vectorize across j (columns) to improve throughput when computing
    // the row for a fixed i. The reduction is over k_row (inner products),
    // which remains scalar.
    const int vec_width = Halide::natural_vector_size(target, type_of<num_t>());
    if (vec_width > 1) {
        row_upper.vectorize(j_var, vec_width);
    }

    // JIT-compile the scalar and row pipelines once; we will reuse them.
    left_elem.compile_jit(target);
    row_upper.compile_jit(target);

    // Temporary buffer to hold a full row of updated A[i][j] for j = 0..n-1.
    // We will only write back the portion j >= i to A.
    Halide::Buffer<num_t> row_tmp(n);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // First inner loop: j = 0 .. i-1 (lower-triangular "L" part)
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e., A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1 (upper-triangular "U" part)
        //
        // Instead of one Halide call per (i, j), we compute the entire row
        // A[i][j] - sum_{k<i} A[i][k]*A[k][j] for all j with a single
        // 1D pipeline call per i. This improves locality and reduces
        // JIT/dispatch overhead.
        row_upper.realize(row_tmp);

        // Copy only the j >= i entries back into A. Entries j < i have
        // already been updated in the first inner loop and must be kept.
        for (int j = i; j < n; j++) {
            A(j, i) = row_tmp(j);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

